    public function handle(): int
    {
        $made = 0;
        foreach (array_merge(self::RULES, self::MORE) as [$name, $mod, $field, $op, $val, $msg, $every]) {
            if (DB::table('alert_rules')->where('name', $name)->exists()) continue;

            DB::table('alert_rules')->insert([
                'id' => (string) Str::uuid(), 'name' => $name,
                'mod' => $mod, 'field' => $field, 'op' => $op, 'val' => $val, 'msg' => $msg,
                'chan' => 'داخل النظام', 'every' => $every,
                'status' => 'متوقفة',           // كلها متوقفة — المستخدم يفعّل ما يريد
                'notes' => 'قاعدة انطلاقية جاهزة — فعّلها إن ناسبتك وعدّل قيمها بحرية',
                'created_at' => now(), 'updated_at' => now(),
            ]);
            $made++;
        }

        // تصحيح المنشآت القائمة: قاعدة «تجاوز الميزانية» القديمة كانت وهمية
        // (أكبر من صفر تشتعل لأي تكلفة) — تُرقّى للمقارنة الحقيقية دون مساس بتفعيلها
        $fixed = DB::table('alert_rules')
            ->where('name', '📉 مشروع تجاوز ميزانيته')
            ->where('op', 'أكبر من')->where('val', '0')
            ->update(['op' => 'أكبر من عمود', 'val' => 'budget', 'updated_at' => now()]);

        $this->info(($made
            ? "أُنشئت {$made} قاعدة تنبيه متوقفة — فعّل ما يناسبك من شاشة قواعد التنبيه"
            : 'كل قواعد الانطلاق موجودة أصلاً') . ($fixed ? " · صُحّحت قاعدة الميزانية الوهمية" : ''));

        return self::SUCCESS;
    }
